import{z as p,x as E,o as r,c as d,q as o,j as t,D as a,d as n,s,S as i}from"./chunks/framework.C8m1ZpeB.js";const L=JSON.parse('{"title":"异步 rollout 架构","description":"","frontmatter":{"title":"异步 rollout 架构","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/async-rollout-arch.md","filePath":"llm/async-rollout-arch.md","lastUpdated":1791063341000}'),h={name:"llm/async-rollout-arch.md"};function c(A,e,g,u,m,B){const l=E("Mermaid");return r(),d("div",null,[e[2]||(e[2]=o('<h1 id="异步-rollout-架构" tabindex="-1">异步 rollout 架构 <a class="header-anchor" href="#异步-rollout-架构" aria-label="Permalink to &quot;异步 rollout 架构&quot;">​</a></h1><div class="epigraph"><p>同步 RLHF 把生成、准备、训练收成逐步栅栏；异步把生成变成持续服务，训练变成消费流，用版本号代替「这一批必须同一权重」。</p><footer>—— 对照 Sheng 等 HybridFlow 的三阶段数据流，以及 Fu 等 AReaL 对完全解耦的定义</footer></div><p>在线策略梯度需要「用当前策略采样，再在这些样本上更新」。落到集群上，这句话变成一条<strong>时序契约</strong>：生成引擎的权重与训练引擎的 \\(\\pi_{\\theta}\\) 可以差多少。同步架构（DeepSpeed-Chat Hybrid Engine、早期 verl SPMD rollout、默认 GRPO 脚本）用栅栏保证差为零或一步。长思维链与工具延迟让栅栏的等待变成主墙钟。<a href="/llm/areal-async-rl">AReaL</a> 把契约改成流式；<a href="/llm/openrlhf">OpenRLHF</a> 写异步 dataflow；verl v0.7 默认改 <strong>server 模式</strong>；<a href="/llm/slime-rl">slime</a> 提供 fully_async 例。本篇把这些实现收成同一张架构图：共置同步、一步重叠、完全异步，以及必须记账的 staleness 与 partial rollout。算法公式仍指向 <a href="/llm/schulman-ppo">PPO</a> / <a href="/llm/grpo">GRPO</a>，这里只写系统时序。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>HybridFlow（Sheng、Zhang、Peng、Lin、Wu 等，EuroSys 2025，arXiv:2409.19256）把 RLHF 写成数据流：节点是分布式 LLM 程序（生成 / 前向 / 反向），边是重切分多播。PPO 一步典型三阶段——生成、用 ref/RM/critic 准备、更新 actor——在同步执行里顺序发生。3D-HybridEngine 优化的是<strong>同一批 GPU 上</strong>训练布局与生成布局之间的零冗余重切分，吞吐相对当时基线 1.53×–20.57×。它不消灭「等最长序列」。推理模型把该等待从秒级拉到分钟级，加卡反而减小每卡 decode batch，更不划算。</p><p>异步要回答的问题因此不是「会不会 HybridFlow」，而是：<strong>栅栏能否拆开，拆开后梯度还对不对</strong>。One-step overlap 仍保持 batch 内同版本，只把「上一步训练」与「当前步生成」叠在不同资源上。完全异步允许一个训练 batch 混合多个版本，甚至一条序列在解码中途换权重。</p><p><span class="marginnote">「staleness」（陈旧度）指样本生成时用的权重版本，与当前正在训练的权重版本差了几步。差 0–1 步还能近似当 on-policy；差上 5 步，重要性比就可能飘出合理范围，clip 也压不住——所以异步系统都要给它设上限。</span></p><h3 id="三种时序不是实现细节" tabindex="-1">三种时序不是实现细节 <a class="header-anchor" href="#三种时序不是实现细节" aria-label="Permalink to &quot;三种时序不是实现细节&quot;">​</a></h3><ol><li><strong>同步栅栏</strong>：\\(\\pi_{\\mathrm{old}}\\) 全局唯一；实现简单；气泡 = 长尾。</li><li><strong>一步重叠</strong>：资源利用率高一截；算法仍可当 on-policy（差一步）；最长序列问题还在。</li><li><strong>完全异步 / 流式</strong>：生成是 server，请求完成即入队；必须有 staleness 上限、版本化 logprob、以及是否允许 partial rollout。</li></ol><p><span class="marginnote">直觉类比：一步重叠像后厨「上一锅炒着、下一锅备着」，锅与锅之间还是同一版菜单；完全异步则是自助餐，训练随到随吃，代价是每盘菜都得贴上生产日期（版本号），坏了哪盘能追溯。</span></p><p>把 vLLM sleep 模式的共置时间片（OpenRLHF Hybrid Engine 文档：生成与训练轮流占卡）当成第 3 种是错误：那是<strong>时间复用的同步</strong>，不是流。</p><p><span class="marginnote">verl v0.7 去掉 SPMD rollout、默认 server 模式，主因是多轮与动态批，不一定等于 AReaL 式训练–生成分节点。Server 模式仍可逐步对齐权重再开训。读发行说明，不要把「server」等同「off-policy」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>架构上把角色拆开：<strong>Rollouter</strong>（常驻推理服务，vLLM / SGLang / TensorRT-LLM）、<strong>Learner</strong>（FSDP / Megatron / ZeRO）、<strong>Controller</strong>（单进程编排，HybridFlow 的 single-controller）、可选 <strong>Reward pool</strong>。同步实现里 Controller 调用 <code>generate_sequences</code>，阻塞直到 batch 满且全部结束，再 <code>update</code>。异步实现里 Rollouter 不阻塞在 batch 边界：Controller 用队列长度与 \\(\\eta\\) 做反压（AReaL 的 \\(\\lfloor(N_r-1)/B\\rfloor\\le i+\\eta\\)），Learner 可独立 step。</p><p>权重同步是第二条边。共置重切分（3D-HybridEngine、vLLM sleep）延迟低、实现重。分置广播（OpenRLHF 切片管道、slime NCCL/delta、NeMo-Aligner 的 TensorRT refit）延迟高、调度自由。异步把这条边从「生成临界路径」上挪走：训练结束就推权重，生成侧可中断或等下一条请求再加载。Partial / interruptible rollout：未完成序列要么丢弃（浪费）、要么带着旧前缀继续（必须重算 KV 或接受混版本）。AReaL 选择中断 + 重算前缀。</p>',15)),(r(),t(i,null,{default:a(()=>[s(l,{id:"mermaid-57",class:"mermaid",graph:"flowchart%20TB%0A%20%20subgraph%20sync%5B%22%E5%90%8C%E6%AD%A5%E6%A0%85%E6%A0%8F%22%5D%0A%20%20%20%20G1%5B%22%E7%94%9F%E6%88%90%E6%95%B4%E6%89%B9%22%5D%20--%3E%20T1%5B%22%E8%AE%AD%E7%BB%83%22%5D%0A%20%20%20%20T1%20--%3E%20G1%0A%20%20end%0A%20%20subgraph%20async%5B%22%E5%AE%8C%E5%85%A8%E5%BC%82%E6%AD%A5%22%5D%0A%20%20%20%20RO%5B%22%E6%8C%81%E7%BB%AD%20Rollout%20%E6%9C%8D%E5%8A%A1%22%5D%20--%3E%20Q%5B%22%E5%B8%A6%E7%89%88%E6%9C%AC%E7%9A%84%E9%98%9F%E5%88%97%22%5D%0A%20%20%20%20Q%20--%3E%20LR%5B%22Trainer%20%E6%B6%88%E8%B4%B9%22%5D%0A%20%20%20%20LR%20--%3E%7C%22weight%20v%22%7C%20RO%0A%20%20end%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[n(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=o('<h3 id="控制面仍可以是单控制器" tabindex="-1">控制面仍可以是单控制器 <a class="header-anchor" href="#控制面仍可以是单控制器" aria-label="Permalink to &quot;控制面仍可以是单控制器&quot;">​</a></h3><p>HybridFlow 的论点是：节点<strong>之间</strong>用单控制器写数据依赖，节点<strong>之内</strong>用多控制器跑 Megatron/FSDP，避免 RLLib 式把每个算子都从中心派发。异步不推翻这一点。AReaL 的 Rollout Controller、verl 的 AgentLoopManager、OpenRLHF 的 Ray 驱动，都是单控制器；变的是 <code>generate</code> 是否阻塞。多控制器把「何时更新」写进每个 worker 的本地循环，数据流一改就要改所有角色——正是 HybridFlow 要避免的。异步框架若把 staleness 逻辑复制到每个生成 worker，会回到多控制器的维护成本。</p><p><span class="marginnote">EuroSys 论文对照含 OpenRLHF 早期、DeepSpeed-Chat、NeMo-Aligner 等，倍数跨度 1.53–20.57 来自不同算法与规模，不能摘一个 20× 当异步 RL 的通用广告。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>正确性依赖三本账。<strong>版本</strong>：每条样本记录生成时的 policy version，重要性比 \\(\\pi_\\theta/\\pi_{\\mathrm{behav}}\\) 用对。<strong>近端中心</strong>：完全异步时不要把过期的 \\(\\pi_{\\mathrm{behav}}\\) 既当行为策略又当 clip 中心，AReaL 的解耦 PPO 把 \\(\\pi_{\\mathrm{prox}}\\) 取较新锚。<strong>Mask 与 token 身份</strong>：流式多轮必须 token-in token-out，否则队列里的字符串再分词会与 logprob 错位，见 <a href="/llm/agentloop-server">AgentLoop</a>。</p>',5)),(r(),t(i,null,{default:a(()=>[s(l,{id:"mermaid-73",class:"mermaid",graph:"flowchart%20TD%0A%20%20R%5B%22Rollouter%20%E7%94%A8%E6%9D%83%E9%87%8D%20v7%20%E7%94%9F%E6%88%90%E6%A0%B7%E6%9C%AC%22%5D%20--%3E%20Q%5B%22%E6%A0%B7%E6%9C%AC%E5%85%A5%E9%98%9F%5Cn%E8%B4%B4%E7%89%88%E6%9C%AC%E5%8F%B7%207%20%E4%B8%8E%E9%80%90%20token%20logprob%22%5D%0A%20%20Q%20--%3E%20T%5B%22Learner%20%E5%B7%B2%E6%8E%A8%E8%BF%9B%E5%88%B0%20v9%5Cn%E6%B6%88%E8%B4%B9%E8%BF%99%E6%9D%A1%E6%A0%B7%E6%9C%AC%22%5D%0A%20%20T%20--%3E%20W%5B%22%E9%87%8D%E8%A6%81%E6%80%A7%E6%AF%94%EF%BC%9A%E5%88%86%E5%AD%90%20%CF%80_%CE%B8%20v9%5Cn%E5%88%86%E6%AF%8D%20%CF%80_behav%20%E5%BF%85%E9%A1%BB%E6%98%AF%20v7%22%5D%0A%20%20T%20--%3E%20P%5B%22clip%20%E4%B8%AD%E5%BF%83%20%CF%80_prox%20%E5%8F%96%E8%BE%83%E6%96%B0%E9%94%9A%5Cn%E4%B8%8D%E8%83%BD%E6%8B%BF%E8%BF%87%E6%9C%9F%20v7%20%E5%BD%93%E4%B8%AD%E5%BF%83%22%5D%0A"})]),fallback:a(()=>[...e[1]||(e[1]=[n(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=o('<p><span class="marginnote">为什么 token 对齐这一步错不得：同一段文本换一种分词可能切出不同的 token 序列，重新分词后的第 37 个 token 未必对应原 logprob 表里的第 37 个。序列看似在训，重要性比整条错位——训练还在跑，学到的却是噪声。</span></p><p>吞吐来自重叠与减填充，不是来自更大的学习率。反压 \\(\\eta\\) 是在「利用率」和「偏差」之间的旋钮：\\(\\eta=0\\) 退回同步；\\(\\eta\\) 过大时即使 clip 也救不回分布。工具调用时，异步的收益还来自轨迹间不在 I/O 上对齐，这是 <a href="/llm/verltool">VERLTool</a> 的 2× 来源，即使 Learner 仍逐步训练。</p><h3 id="资源切分与算法切分" tabindex="-1">资源切分与算法切分 <a class="header-anchor" href="#资源切分与算法切分" aria-label="Permalink to &quot;资源切分与算法切分&quot;">​</a></h3><p>分池（生成卡 / 训练卡）是资源异步；允许混版本是算法异步。可以分池但仍栅栏（生成池跑完一整批再训），那只是硬件解耦。可以共置但仍流式（同一组卡上推理服务不停、训练插空），那是调度异步。写设计文档时分开，否则无法解释「为什么加了 vLLM 还是在等长尾」。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>调试永远先 \\(\\eta=0\\)。日志必须能重建每条轨迹的版本向量，否则塌了无法归因。权重推送频率与中断成本要 profile：过于频繁会把 decode 变成 prefill。不要把 server 模式的动态批（提高多轮吞吐）与 off-policy 混为一谈。不要在未改目标函数时复制 AReaL 的中断生成。集群网络若撑不住分置广播，共置同步可能仍更快——异步不是层级关系，是长尾足够肥时才划算。奖励服务若与生成串行，工具或单测会重新引入栅栏：把 CPU 验证器做成可水平扩展的池，是 AReaL 把「并行奖励」写进系统贡献的原因，也适用于任何自称异步的栈。</p><p><span class="marginnote">Sheng 等 <em>HybridFlow</em>，arXiv:2409.19256，DOI 10.1145/3689031.3696075，代码 <code>volcengine/verl</code>。Fu 等 AReaL arXiv:2505.24298。Hu 等 OpenRLHF arXiv:2405.11143。Yao 等 DeepSpeed-Chat arXiv:2308.01320。Kwon 等 vLLM SOSP 2023。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>异步 rollout 拆的是生成–训练栅栏；HybridEngine 拆的是同卡上的布局切换。两者正交。</li><li>完全异步必须版本化样本、限制 staleness、并决定是否允许跨版本拼接的 partial rollout。</li><li>Server 化推理提高多轮动态批，本身不等于 off-policy。</li><li>出处：HybridFlow EuroSys 2025；AReaL arXiv:2505.24298；verl v0.7 发行说明。</li></ul>',9))])}const b=p(h,[["render",c]]);export{L as __pageData,b as default};
